<script setup lang="ts">
import { computed, ref } from 'vue'
import corpus from '../data/manual-corpus.json'
import { buildIndex, search } from '../lib/manual-core.mjs'
import { demoSourceUrl, sourceFragment } from '../lib/manual-journey'
import { useManualPlayback } from '../lib/manual-motion'
import ManualMarkedText from './ManualMarkedText.vue'
const index = buildIndex(corpus)
const examples = [{ label: 'CSV export', query: 'export CSV columns', reference: 'cedar-logger#csv-export', note: 'This result retrieves the labelled export section. The original paragraph stays available for verification.' }, { label: 'Literal markup', query: 'literal session label markup', reference: 'cedar-logger#label-literals', note: 'The corpus deliberately includes an HTML-like label. It stays literal text, including inside highlighted spans.' }, { label: 'Unsupported encryption', query: 'encrypted CSV export', reference: 'cedar-logger#csv-export', note: 'CSV and export match, but the paragraph gives no encryption information. The recorded evaluation labels this query unanswerable.' }]
const chosen = ref(0)
const example = computed(() => examples[chosen.value]!)
const result = computed(() => search(index, example.value.query).find(row => row.reference === example.value.reference)!)
const link = computed(() => demoSourceUrl(result.value, { query: example.value.query, manual: result.value.manualId, category: result.value.category }))
const { index: step, pulse, version, reduced, select } = useManualPlayback(() => 3, 2)
const steps = [{ label: 'Stable reference', icon: 'M7 9h34v29H7z M14 18h20 M14 27h12', detail: 'The canonical reference uses manual ID plus section ID. Titles may change without changing identity; paragraph revisions still need a new corpus revision and evaluation.' }, { label: 'Source URL', icon: 'M18 30l-4 4a8 8 0 0 1-11-11l10-10a8 8 0 0 1 11 0 M30 18l4-4a8 8 0 0 1 11 11L35 35a8 8 0 0 1-11 0 M16 32l16-16', detail: 'Query, manual and category remain URL parameters. The source fragment opens the complete section after reload; a new submitted search clears the previous fragment.' }, { label: 'Exact paragraph', icon: 'M10 4h22l7 7v33H10z M32 4v8h7 M17 21h15 M17 28h15 M17 35h11', detail: 'Only lexical tokens are highlighted. Every original character remains text; the source is never passed through an HTML parser or rewritten into a generated answer.' }]
function choose(value: number) { chosen.value = value; select(2) }
</script>
<template>
  <div class="manual-demo" data-testid="manual-attribution"><div class="manual-demo-heading"><p>Interactive source trace</p><h3>Keep the passage attached to the result.</h3></div><div class="manual-options" role="group" aria-label="Source example"><button v-for="(item, position) in examples" :key="item.label" type="button" :aria-pressed="chosen === position" @click="choose(position)">{{ item.label }}</button></div><div class="manual-flow" :class="{ 'is-tracing': pulse }"><button v-for="(item, position) in steps" :key="item.label" type="button" :data-source-step="position" :aria-pressed="step === position" @click="select(position)"><svg :key="version" viewBox="0 0 48 48" aria-hidden="true"><path :d="item.icon" /></svg><strong>{{ item.label }}</strong><span>{{ ['Identity', 'Navigation', 'Original wording'][position] }}</span></button></div><div class="manual-explanation" aria-live="polite"><h4>{{ steps[step].label }}</h4><p>{{ steps[step].detail }}</p><code v-if="step === 0" class="manual-source-code">{{ result.reference }}</code><code v-else-if="step === 1" class="manual-source-code">#{{ sourceFragment(result.manualId, result.sectionId) }}</code></div><div class="manual-source-sheet"><div class="manual-source-meta"><strong>{{ result.manualTitle }}</strong><span>Revision {{ result.revision }} · {{ result.matchedTerms.length }}/{{ result.queryTermCount }} terms matched</span></div><h4>{{ result.sectionTitle }}</h4><p data-testid="manual-exact-source"><ManualMarkedText :text="result.sourceText" :terms="result.matchedTerms" /></p><div class="manual-source-footnote" data-testid="manual-source-note">{{ example.note }}</div><a class="text-link" data-testid="manual-source-link" :href="link">Open the exact source in the demo</a></div><details class="manual-collision"><summary>Why use a dot in the source fragment?</summary><p>The original renderer joined IDs with <code>--</code>. Valid pairs <code>a--b#c</code> and <code>a#b--c</code> then collided. A browser regression caught it.</p><code>source-a--b.c<br>source-a.b--c</code><p>A dot is excluded from validated IDs, so the two fragment targets stay distinct.</p></details><p class="manual-demo-note">{{ reduced ? 'Reduced motion is on. ' : '' }}These are original fictional source paragraphs. The link opens the standalone demo with its actual query, filter and source-fragment behavior.</p></div>
</template>
